def maxPairEquation(points, k):
    from collections import deque
    dq = deque()
    best = None
    for x, y in points:
        while dq and x - dq[0][1] > k:
            dq.popleft()
        if dq:
            cand = dq[0][0] + y + x
            if best is None or cand > best:
                best = cand
        v = y - x
        while dq and dq[-1][0] <= v:
            dq.pop()
        dq.append((v, x))
    return best
